    // guard the deferral exists to preserve. The later one wins, and the plain deferral kept it.
    expect(runtime.tick).toBe(3);
    expect(runtime.pendingSeeds).toEqual([]);
    expect(runtime.lastFlushError).toBeUndefined();
    runtime.dispose();
  });

